WITH recent_inventory AS (SELECT * FROM inventory WHERE product_id IN (6, 9) AND product_id IN (5, 9) AND YEAR(last_restock) = 2023), agg AS (SELECT product_id, CASE WHEN quantity >= 204 THEN 'high' WHEN quantity >= 119 THEN 'mid' ELSE 'low' END AS quantity_bucket, MIN(last_restock) AS first_last_restock, ROUND(STDDEV(quantity), 2) AS stddev_quantity FROM recent_inventory GROUP BY product_id, CASE WHEN quantity >= 204 THEN 'high' WHEN quantity >= 119 THEN 'mid' ELSE 'low' END) SELECT product_id, quantity_bucket, first_last_restock, stddev_quantity FROM agg ORDER BY stddev_quantity DESC
